L["Sets the font for the names that float above players, NPCs and enemies in the world.\n\nSeparate from Global Font - changing this does not affect the rest of the UI, and Global Font does not affect it.\n\nBlizzard Default leaves the name text completely untouched.\n\n|cffff4d4dRequires a re-log or restart of WoW to take effect.|r"] = "Fuente de los nombres que flotan sobre los jugadores, los PNJ y los enemigos en el mundo.\n\nEs independiente de la fuente global: cambiar esta no afecta al resto de la interfaz, y la fuente global no le afecta a ella.\n\nPredeterminado de Blizzard deja el texto de los nombres sin tocar.\n\n|cffff4d4dHay que volver a conectarse o reiniciar WoW para que se aplique.|r"
