L["Corner options place the bar flush with that corner of the target and set its grow direction to keep it there as bars change size."] = "Las opciones de esquina pegan la barra a esa esquina del objetivo y ajustan su dirección de crecimiento para que siga ahí cuando las barras cambien de tamaño."
L["The taintLog and scriptProfile CVars are enabled."] = "Las CVar taintLog y scriptProfile están activadas."
L["The taintLog CVar is enabled."] = "La CVar taintLog está activada."
L["The scriptProfile CVar is enabled."] = "La CVar scriptProfile está activada."
L["It reduces performance and should be off unless you are capturing a bug report."] = "Reduce el rendimiento y debería estar desactivada salvo que estés grabando un informe de error."
L["A reload is required to apply this."] = "Hay que recargar para aplicar esto."
L["Type /reload in chat to apply."] = "Escribe /reload en el chat para aplicarlo."
L["Reload to finish importing."] = "Recarga para terminar de importar."
L["Cannot reload during combat. Type /reload instead."] = "No se puede recargar en combate. Escribe /reload."
L["Flat, clean and modern. The look EllesmereUI was designed around."] = "Plano, limpio y moderno. El aspecto para el que se diseñó EllesmereUI."
L["Blizzard's own frame and button art, with EllesmereUI's features."] = "El arte de marcos y botones del propio Blizzard, con las funciones de EllesmereUI."
L["The original frames, rings and slots where the game has them, with EllesmereUI's features."] = "Los marcos, anillos y casillas originales donde el juego los tiene, con las funciones de EllesmereUI."
L["Style changed for this profile. A UI reload is needed to apply it."] = "Se ha cambiado el estilo de este perfil. Hay que recargar la interfaz para aplicarlo."
L["Same setup, same EllesmereUI features, a new look: switch to Blizzard Style or the new Classic WoW UI in one click, and switch back any time."] = "La misma configuración y las mismas funciones de EllesmereUI con un aspecto nuevo: cambia al estilo de Blizzard o a la nueva interfaz de WoW Clásico con un clic, y vuelve cuando quieras."
L["Global Settings > Style sets the look for the whole UI or for each module."] = "Ajustes globales > Estilo elige el aspecto de toda la interfaz o de cada módulo."
L["Patch 12.1 changes a lot, and EllesmereUI changed with it. This video walks you through the most important changes so you can jump straight back in. Copy the link below and watch it in your browser."] = "El parche 12.1 cambia muchas cosas, y EllesmereUI ha cambiado con él. Este vídeo te enseña los cambios más importantes para que vuelvas a jugar enseguida. Copia el enlace de abajo y míralo en tu navegador."
L["Watch anytime: the link also lives at the top of Patch Notes."] = "Míralo cuando quieras: el enlace también está arriba en las notas del parche."
L["Settings Overrides are the most powerful system in EllesmereUI, and the deepest. A few minutes with this video will save you hours of working it out on your own."] = "Los ajustes por especialización o condición son el sistema más potente de EllesmereUI, y el más complejo. Unos minutos con este vídeo te ahorrarán horas de averiguarlo por tu cuenta."
L["You changed the default value of a setting that has overrides. Overrides keep their own values, so this change will not reach the specs or conditions they cover. To change it for an override, pick that override from the class glyph beside the module search bar and edit it there."] = "Has cambiado el valor predeterminado de un ajuste que tiene ajustes por especialización o condición. Esos mantienen sus propios valores, así que este cambio no llegará a las especializaciones o condiciones que cubren. Para cambiarlo en uno de ellos, elígelo desde el glifo de clase junto a la barra de búsqueda del módulo y edítalo allí."
L["Gold border settings have overrides. Hover info icon for details."] = "Los ajustes del borde dorado tienen ajustes por especialización o condición. Pasa el ratón por el icono de información para ver los detalles."
L["Popular presets now live on the new EllesmereUI website including full previews, step-by-step install instructions, plus new presets added every day!"] = "Los preajustes populares ahora están en la nueva web de EllesmereUI, con vistas previas completas, instrucciones de instalación paso a paso ¡y preajustes nuevos cada día!"
L["Each preset's page includes its import string."] = "La página de cada preajuste incluye su texto de importación."
L["This profile string does not carry any global settings."] = "Este texto de perfil no trae ajustes globales."
L["Apply the sharer's fonts, custom colours, dark mode, accent colour and UI scale. Off = keep your own global look and scale; only the selected modules' settings come in."] = "Aplica las fuentes, los colores personalizados, el modo oscuro, el color de acento y el tamaño de la IU de quien lo comparte. Desactivado = mantienes tu aspecto global y tu tamaño; solo entran los ajustes de los módulos elegidos."
L["Reload to finish switching to the new profile."] = "Recarga para terminar de cambiar al perfil nuevo."
L[" Mouseover is sealed here too for this element: its hover mechanism follows the shared setting, so an override could only leave it shown."] = " Para este elemento, el modo al pasar el ratón también está bloqueado aquí: su forma de mostrarse al pasar el ratón sigue el ajuste común, así que un ajuste propio solo podría dejarlo visible."
L["This element cannot use group-based visibility."] = "Este elemento no puede usar la visibilidad por grupo."
L["Requires a client with gliding events."] = "Necesita un cliente con eventos de planeo."
L["Not available while a legacy visibility value is selected. Pick Never or Always first."] = "No está disponible mientras haya elegido un valor de visibilidad antiguo. Elige antes Nunca o Siempre."
L["Scales the text size of Blizzard tooltips."] = "Ajusta el tamaño del texto de las descripciones de Blizzard."
L["Sizes the movement alert's free text, bar number and icon countdown. Switching the alert's Display Mode re-seeds this value."] = "Ajusta el tamaño del texto libre, el número de la barra y la cuenta atrás del icono del aviso de movimiento. Cambiar el modo de visualización del aviso vuelve a poner este valor."
L["%1$s is active: the tracker keeps Blizzard's own text."] = "%1$s está activo: el seguimiento mantiene el texto propio de Blizzard."
L["Size of the Classic frame around the bar."] = "Tamaño del marco clásico alrededor de la barra."
L["%1$s is active. Settings that only apply to the EllesmereUI look are hidden."] = "%1$s está activo. Se ocultan los ajustes que solo se aplican al aspecto de EllesmereUI."
L["Changing the style requires a UI reload to apply."] = "Hay que recargar la interfaz para aplicar el cambio de estilo."
L["Your setup and every EllesmereUI feature carry over; only the look changes. Apply a style to every module in one click, or set each module below. Changing a style reloads the UI."] = "Tu configuración y todas las funciones de EllesmereUI se mantienen; solo cambia el aspecto. Aplica un estilo a todos los módulos con un clic o elige el de cada módulo abajo. Cambiar de estilo recarga la interfaz."
L["Texture for every unit frame cast bar. Inherit follows each unit's bar texture."] = "Textura de la barra de hechizos de todos los marcos de unidad. Heredar usa la textura de la barra de cada unidad."
L["Texture for the health, power and class resource bars."] = "Textura de las barras de salud, de poder y de recurso de clase."
L["%1$s is active: chat keeps Blizzard's own background and tab art."] = "%1$s está activo: el chat mantiene el fondo y las pestañas de Blizzard."
L["Used by the movement alert's Bar display mode."] = "La usa el modo de visualización Barra del aviso de movimiento."
L["*Blizzard's auto targeting (soft target) setting can cause brief flickering when your actual target dies but a soft-target is still active."] = "*El ajuste de selección automática de Blizzard (objetivo flexible) puede hacer que parpadee un momento cuando tu objetivo real muere pero aún hay un objetivo flexible activo."
L["Addon not loaded"] = "Addon no cargado"
L["Anchor to Cursor"] = "Anclar al cursor"
L["Apply X to all Bars"] = "Aplicar X a todas las barras"
L["at least one Celebration Trigger"] = "al menos un activador de celebración"
L["Choose which addons to import. Any addons not included will use your active profile's settings in the new profile."] = "Elige qué addons importar. Los que no incluyas usarán en el perfil nuevo los ajustes de tu perfil activo."
L["Choose which addons you want enabled. You can change any of these later in the EllesmereUI settings panel."] = "Elige qué addons quieres activar. Puedes cambiar cualquiera más tarde en el panel de ajustes de EllesmereUI."
L["Coming soon"] = "Próximamente"
L["Configure alerts for missing Beacon of Light or Faith."] = "Configura avisos para cuando falte Señal de la Luz o Señal de la fe."
L["Controls the text rendering style used across all UI elements"] = "Controla el estilo con el que se dibuja el texto en todos los elementos de la interfaz"
