L["Shows only debuffs that match every checked Show filter (dispel types count as one); opposites like Non-Player Auras with Cast By You, or a filter an indicator shows, show nothing."] = "Solo muestra los perjuicios que cumplen todos los filtros marcados (los tipos de disipación cuentan como uno); si combinas filtros opuestos, como Auras de no jugadores con Lanzados por ti, o un filtro que ya muestra un indicador, no se muestra nada."
L["Attached widens each frame by the portrait."] = "Unido hace cada marco más ancho con el retrato."
