L["Show the crafted quality rank on tracked items, matching the rank icon on the action bars. Items with no crafted quality are unaffected."] = "Muestra el rango de calidad de fabricación en los objetos seguidos, igual que el icono de rango de las barras de acción. No afecta a los objetos sin calidad de fabricación."
