L["Keep keybind text identical when your action bar swaps -- rogue stealth, druid forms, skyriding. Also covers conditional macros like \"/cast [bonusbar:1] Backstab; Shadow Dance\", where the key would otherwise jump to whichever branch is live.\n\nThe key then only changes when you actually move the ability or rebind it.\n\nOn by default. Applies to every CDM bar at once."] = "Mantiene igual el texto del atajo cuando cambia tu barra de acción: sigilo del pícaro, formas del druida, surcacielos. También vale para macros condicionales como «/cast [bonusbar:1] Backstab; Shadow Dance», donde la tecla saltaría a la rama que esté activa.\n\nAsí la tecla solo cambia cuando mueves de verdad la facultad o le cambias el atajo.\n\nActivado de forma predeterminada. Se aplica a todas las barras del CDM a la vez."
