L["This is the spec you're syncing from -- it's always included."] = "Es la especialización desde la que sincronizas: siempre está incluida."
L["How extra columns grow when the second column appears or disappears. Grow Right keeps the left column in place, Grow Left keeps the right column in place, Grow Centered keeps the bar centered."] = "Cómo crecen las columnas extra cuando aparece o desaparece la segunda columna. Crecer a la derecha deja la columna izquierda en su sitio, Crecer a la izquierda deja la columna derecha en su sitio y Crecer centrado mantiene la barra centrada."
L["Not available while a spell on this bar uses a Cooldown State Shift Icons setting"] = "No disponible mientras un hechizo de esta barra use el ajuste de estado de reutilización Mover iconos"
L["When the current spec has no bars in this group, keeps elements anchored to the group in place and shifts them up or down by one bar height (tune with the cog's Extra Y Offset) to cover its empty slot."] = "Cuando la especialización actual no tiene barras en este grupo, deja en su sitio los elementos anclados al grupo y los mueve arriba o abajo la altura de una barra (ajústalo con Desplazamiento Y extra en el engranaje) para tapar el hueco vacío."
