L["Share this group's name, layout, and position across all specs."] = "Comparte el nombre, la disposición y la posición de este grupo en todas las especializaciones."
L["Thickness of the Pixel Glow applied to this bar's buff icons."] = "Grosor del brillo de píxeles de los iconos de beneficios de esta barra."
L["This bar will always be attached to your current target's nameplate"] = "Esta barra siempre estará unida a la placa de nombre de tu objetivo actual"
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Spells you added yourself (presets, custom IDs and racials) are kept. Continue?"] = "Esto restablece todos los hechizos asignados a las barras predeterminadas de la especialización actual para que coincidan con el diseño del CDM de Blizzard. Se conservan los hechizos que añadiste tú (plantillas, ID personalizados y raciales). ¿Continuar?"
