L["A raid control panel with ready check, pull timer and raid markers. In a raid it only shows while you are the leader or an assistant, since none of its buttons work without that; in a party it always shows."] = "Un panel de control de banda con comprobación de listos, temporizador de pull y marcas de banda. En una banda solo se ve si eres el líder o un ayudante, porque sin eso no funciona ninguno de sus botones; en un grupo se ve siempre."
