L["Bar-style class resources (Insanity, Maelstrom, Astral Power, etc.) use Blizzard's default player frame bar artwork instead of the texture above."] = "Los recursos de clase de tipo barra (Demencia, Vorágine, Poder Astral, etc.) usan el dibujo de barra del marco del jugador predeterminado de Blizzard en lugar de la textura de arriba."
L["Blizzard's bar artwork is never recolored, so fill color modes and threshold colors will not tint the bar while this is enabled. To keep threshold colors visible, use Recolor Text Instead."] = "El dibujo de las barras de Blizzard nunca cambia de color, así que los modos de color del relleno y los colores del umbral no tiñen la barra mientras esto esté activado. Para seguir viendo los colores del umbral, usa Colorear el texto en lugar de la barra."
L["Show the bar full of its fill color while no global cooldown is running, instead of the background color."] = "Muestra la barra llena con el color del relleno cuando no hay tiempo de reutilización global, en lugar del color de fondo."
L["Opacity of the resource fill; below 100 the world shows through the fill instead of the background."] = "Opacidad del relleno del recurso; por debajo de 100 se ve el mundo a través del relleno en lugar del fondo."
