L["This option requires Countdown Format to count GCDs inside Arcane Soul"] = "Esta opción necesita que Formato de la cuenta atrás cuente los GCD dentro de Arcane Soul"
L["Power Value | Power %"] = "Valor de poder | Poder %"
L["Shift Elements if No Resource"] = "Mover los elementos si no hay recurso"
L["Vertical Down"] = "Vertical hacia abajo"
L["Vertical Up"] = "Vertical hacia arriba"
L["One bar per weapon that can swing, each filling over the time to the next auto attack."] = "Una barra por cada arma que pueda golpear; cada una se llena con el tiempo que falta para el siguiente ataque automático."
L["Height of each weapon row."] = "Altura de cada fila de arma."
L["Gap between the weapon rows."] = "Espacio entre las filas de armas."
L["Hide the bar while no swing is running."] = "Oculta la barra mientras no hay un golpe en marcha."
L["Show an idle row full of its fill color instead of the background color."] = "Muestra una fila en reposo llena con el color del relleno en lugar del color de fondo."
L["Start each row full and drain it as the swing timer elapses, instead of filling it up."] = "Empieza cada fila llena y la vacía según pasa el temporizador de golpes, en lugar de llenarla."
L["Show a small glowing spark that moves along the leading edge of the fill while a swing is running."] = "Muestra una pequeña chispa brillante que avanza por el borde del relleno mientras hay un golpe en marcha."
L["Choose which weapons get a swing row. A row also needs a weapon in that slot."] = "Elige qué armas tienen fila de golpes. Una fila también necesita un arma en ese hueco."
L["Show the off hand as a spark on the Main Hand bar instead of its own row."] = "Muestra la mano izquierda como una chispa en la barra de la mano derecha en lugar de en su propia fila."
L["Show the seconds left to the next swing on each row."] = "Muestra en cada fila los segundos que faltan para el siguiente golpe."
L["Tag each row with its weapon slot: MH (Main Hand), OH (Off Hand), R (Ranged)."] = "Pone en cada fila el hueco de su arma: MH (mano derecha), OH (mano izquierda), R (a distancia)."
L["Dim a row and paint its text red while the current target is out of that weapon's auto attack range."] = "Atenúa una fila y pone su texto en rojo mientras el objetivo actual está fuera del alcance del ataque automático de esa arma."
L["While an on-next-swing attack is queued, the Main Hand and Off Hand rows take its color and show its name (Heroic Strike, Maul and Raptor Strike share one color, Cleave has its own)."] = "Mientras hay un ataque de «siguiente golpe» en cola, las filas de la mano derecha y la izquierda toman su color y muestran su nombre (Heroic Strike, Magullar y Golpe de raptor comparten un color; Rajar tiene el suyo)."
L["Opacity of a row whose target is out of range."] = "Opacidad de una fila cuyo objetivo está fuera de alcance."
L["Current Spec is affected by Threshold & Hash Lines."] = "La especialización actual se ve afectada por Umbral y líneas divisorias."
L["Current Spec is not affected by Threshold & Hash Lines."] = "La especialización actual no se ve afectada por Umbral y líneas divisorias."
L["Thresholds have their own per-spec system and can't be edited while editing a spec group"] = "Los umbrales tienen su propio sistema por especialización y no se pueden editar mientras editas un grupo de especializaciones"
L["Tracking it also makes the fill show Ignore Pain alone; without it the fill shows your total absorb, so other shields can add to it."] = "Si lo sigues, además el relleno muestra solo Ignorar dolor; si no, el relleno muestra toda tu absorción, así que otros escudos pueden sumarse."
L["Shows Sweeping Strikes charges on the resource bar; Unit Frames and the personal Nameplate show them regardless."] = "Muestra las cargas de Golpes de barrido en la barra de recurso; los marcos de unidad y la placa de nombre personal las muestran siempre."
L["Enable the Threshold toggle to use these options."] = "Activa el interruptor Umbral para usar estas opciones."
L["Whirlwind and Sweeping Strikes thresholds only support the 'From' direction."] = "Los umbrales de Torbellino y Golpes de barrido solo admiten la dirección «Desde»."
L["Always on for Whirlwind and Sweeping Strikes charges: range coloring at/above the threshold is the only way these bars can display thresholds."] = "Siempre activado para las cargas de Torbellino y Golpes de barrido: colorear a partir del umbral es la única forma de que estas barras muestren umbrales."
L["Only available with the 'From' direction -- it highlights the pips at/above the threshold."] = "Solo disponible con la dirección «Desde»: resalta los puntos que están en el umbral o por encima."
L["Replaces the class resource bar with Blizzard's own class resource frame, such as Holy Power, Combo Points, Chi, Soul Shards, Arcane Charges, Essence or Runes."] = "Sustituye la barra del recurso de clase por el marco del recurso de clase de Blizzard, como Poder sagrado, Puntos de combo, chi, Fragmentos de alma, Cargas Arcanas, Esencia o Runas."
L["This option can't be used while the Unit Frames class resource is set to Blizzard."] = "Esta opción no se puede usar mientras el recurso de clase de los marcos de unidad esté en Blizzard."
L["This option is not available on this client."] = "Esta opción no está disponible en este cliente."
L["This option can't be used while the Personal Resource Display hides the player frame's class resource."] = "Esta opción no se puede usar mientras Mostrar recursos personales oculte el recurso de clase del marco del jugador."
L["This option requires a class resource that Blizzard shows as its own frame, such as Holy Power, Combo Points, Chi, Soul Shards, Arcane Charges, Essence or Runes."] = "Esta opción necesita un recurso de clase que Blizzard muestre en su propio marco, como Poder sagrado, Puntos de combo, chi, Fragmentos de alma, Cargas Arcanas, Esencia o Runas."
L["This option can't be used while you have the Power Bar Height Matched in the Unlock Mode."] = "Esta opción no se puede usar mientras tengas la altura de la barra de poder igualada en el modo desbloqueo."
L["Draws one frame around the resource bars instead of one per bar."] = "Dibuja un solo marco alrededor de las barras de recursos en lugar de uno por barra."
L["This option requires at least two resource bars to be shown."] = "Esta opción necesita que se muestren al menos dos barras de recursos."
L["This option requires the resource bars to share one orientation."] = "Esta opción necesita que las barras de recursos tengan la misma orientación."
L["This option requires the resource bars to be width matched to each other or to have matching widths."] = "Esta opción necesita que las barras de recursos tengan la anchura igualada entre ellas o la misma anchura."
L["Shows a countdown to the Arcane Soul window over the last seconds of Arcane Surge, then the time left inside it. Sunfury Arcane Mages only."] = "Muestra una cuenta atrás hasta la ventana de Arcane Soul durante los últimos segundos de Oleada Arcana, y luego el tiempo que queda dentro. Solo para magos Arcano de Sunfury."
L["Seconds of Arcane Surge left when the countdown appears. Always in seconds, including in GCD mode."] = "Segundos de Oleada Arcana que quedan cuando aparece la cuenta atrás. Siempre en segundos, también en el modo GCD."
L["Seconds counts the time down in tenths. GCD Count counts whole global cooldowns instead, so inside Arcane Soul it reads as the number of Arcane Barrages that still fit, ending on a coloured LAST. Seconds + GCD in Soul mixes the two: tenths counting down to the window, Barrage count once it opens."] = "Segundos cuenta el tiempo hacia atrás en décimas. Número de GCD cuenta en su lugar tiempos de reutilización globales enteros, así que dentro de Arcane Soul indica cuántas Trombas Arcanas caben todavía y termina con un LAST de color. Segundos + GCD en Soul mezcla los dos: décimas hasta la ventana y número de Trombas cuando se abre."
L["Appends your latency in milliseconds to the cast timer, e.g. 1.8 (42ms)."] = "Añade tu latencia en milisegundos al temporizador del hechizo, p. ej.: 1.8 (42ms)."
L["Apply Border to all Bars"] = "Aplicar el borde a todas las barras"
L["Apply Opacity to all Bars"] = "Aplicar la opacidad a todas las barras"
L["Changes the cast bar color based on the current empower stage. Colors transition from red (stage 1) through yellow to green (max stage)."] = "Cambia el color de la barra de hechizos según la fase de potenciación actual. Los colores pasan del rojo (fase 1) al amarillo y al verde (fase máxima)."
L["Creates a class resource bar for Ignore Pain tracking. To see stack text, you must have Ignore Pain tracked in your Blizzard CDM \"Tracked Buffs\" or \"Tracked Bars\" section."] = "Crea una barra de recurso de clase para seguir Ignorar dolor. Para ver el texto de acumulaciones, tienes que tener Ignorar dolor en la sección «Beneficios rastreados» o «Barras rastreadas» del CDM de Blizzard."
L["Draws a hash line that resets to the right edge when you cast Ignore Pain and slides left as the buff runs out."] = "Dibuja una línea divisoria que vuelve al borde derecho cuando lanzas Ignorar dolor y se desliza a la izquierda según se acaba el beneficio."
L["Enable the toggle to set a custom gap color"] = "Activa el interruptor para elegir un color propio para los huecos"
L["Guardian Druid Ironfur Bar"] = "Barra de Pelaje férreo del druida Guardián"
L["Hides this element while you are on a skyriding (glide-capable) mount, where Blizzard shows its vigor HUD."] = "Oculta este elemento mientras vas en una montura de surcacielos (que puede planear), donde Blizzard muestra su indicador de vigor."
L["Highlights the final damage tick. Requires a supported channeled spell."] = "Resalta la última marca de daño. Necesita un hechizo canalizado compatible."
L["Keep the GCD bar visible (sitting empty) when no global cooldown is running, instead of hiding it."] = "Mantiene visible la barra de GCD (vacía) cuando no hay tiempo de reutilización global, en lugar de ocultarla."
L["Latency Overlay"] = "Capa de latencia"
L["Only show the GCD bar for instant-cast abilities. While hard-casting or channeling a spell, the bar stays hidden (the cast bar already shows that progress)."] = "Solo muestra la barra de GCD con las facultades instantáneas. Mientras lanzas o canalizas un hechizo, la barra sigue oculta (la barra de hechizos ya muestra ese avance)."
L["Only show the GCD bar while in a dungeon, raid, arena or battleground."] = "Solo muestra la barra de GCD en mazmorras, bandas, arenas o campos de batalla."
L["Player Cast Bar"] = "Barra de hechizos del jugador"
L["Power Colored"] = "Color de poder"
L["Replaces the class resource bar with an Ironfur tracker. Each Ironfur cast adds a hash line that slides from right to left as its buff decays. Duration is talent-aware (Ursoc's Endurance and Guardian of Elune)."] = "Sustituye la barra del recurso de clase por un contador de Pelaje férreo. Cada Pelaje férreo que lanzas añade una línea divisoria que se desliza de derecha a izquierda según se acaba su beneficio. La duración tiene en cuenta los talentos (Robustez de Ursoc y Guardián de Elune)."
L["Requires Enhancement Shaman with Class Resource enabled."] = "Necesita chamán Mejora con el recurso de clase activado."
L["Resource Text"] = "Texto del recurso"
L["Select a class above"] = "Elige una clase arriba"
L["Shifts any elements anchored to the class resource bar up or down to offset the missing class resource."] = "Mueve arriba o abajo los elementos anclados a la barra del recurso de clase para compensar que falte el recurso de clase."
L["Shifts any elements anchored to the power bar up or down to offset the missing power bar. Applies both when the Power Bar is disabled and for specs that have no power (for example, Beast Mastery and Marksmanship Hunters, whose Focus shows as the class resource bar)."] = "Mueve arriba o abajo los elementos anclados a la barra de poder para compensar que falte la barra de poder. Sirve tanto cuando la barra de poder está desactivada como en especializaciones sin poder (por ejemplo, los cazadores Bestias y Puntería, cuyo enfoque se muestra como barra del recurso de clase)."
L["Show a small glowing spark that moves along the leading edge of the fill."] = "Muestra una pequeña chispa brillante que avanza por el borde del relleno."
L["Shows a bar that fills over the global cooldown."] = "Muestra una barra que se llena durante el tiempo de reutilización global."
L["Shows a colored overlay at the end of the cast bar representing your network latency for each spell. Helps you time spell queuing."] = "Muestra una capa de color al final de la barra de hechizos con tu latencia de red en cada hechizo. Te ayuda a calcular cuándo encadenar hechizos."
L["Shows elapsed / total duration (e.g. 0.4 / 2.0) instead of counting down from the total."] = "Muestra la duración pasada / total (p. ej.: 0.4 / 2.0) en lugar de una cuenta atrás desde el total."
L["Shows tick marks on channeled spells. Only supported spells are shown, request missing spells on Discord."] = "Muestra marcas en los hechizos canalizados. Solo salen los hechizos compatibles; pide los que falten en Discord."
L["Start the bar full and drain it as the global cooldown elapses, instead of filling it up."] = "Empieza la barra llena y la vacía según pasa el tiempo de reutilización global, en lugar de llenarla."
L["this bar"] = "esta barra"
L["This option can't be used while Expand Power Bar if No Resource is enabled."] = "Esta opción no se puede usar mientras Ampliar la barra de poder si no hay recurso esté activado."
L["This option can't be used while Shift Elements if No Resource is enabled."] = "Esta opción no se puede usar mientras Mover los elementos si no hay recurso esté activado."
L["Threshold Color"] = "Color del umbral"
L["Tick Markers"] = "Marcas"
L["When enabled, BM and MM specs show Focus as the standard power bar instead of a class resource bar."] = "Si lo activas, las especializaciones Bestias y Puntería muestran el enfoque como barra de poder normal en lugar de como barra del recurso de clase."
L["Draw tick lines across the bar at positions you choose."] = "Dibuja marcas en la barra en las posiciones que elijas."
L["Add \"%1$s\" to every spec? It will be copied to each of your specs that doesn't already have it."] = "¿Añadir «%1$s» a todas las especializaciones? Se copiará en cada especialización que aún no lo tenga."
L["CDM Bar - %s"] = "Barra del CDM - %s"
L["Hash at %1$s"] = "Línea en %1$s"
L["+ Add Buff"] = "+ Añadir beneficio"
L["Active spec uses Advanced settings"] = "La especialización activa usa los ajustes avanzados"
L["Add Threshold"] = "Añadir umbral"
L["Already used by another card for this spec"] = "Ya lo usa otra tarjeta en esta especialización"
L["Anchor the text inside the bar. The X/Y offsets move it from there."] = "Ancla el texto dentro de la barra. Los desplazamientos X/Y lo mueven desde ahí."
L["Arms Warrior Sweeping Strikes Bar"] = "Barra de Golpes de barrido del guerrero Armas"
L["Attach the spell icon to the right of the cast bar instead of the left."] = "Pone el icono del hechizo a la derecha de la barra de hechizos en lugar de a la izquierda."
L["Bear"] = "Oso"
L["Buff Colors"] = "Colores de los beneficios"
L["Caster"] = "Lanzador de hechizos"
L["Cat"] = "Felino"
L["Choose the color of recharging runes instead of a dimmed version of the rune color."] = "Elige el color de las runas que se recargan en lugar de una versión más apagada del color de la runa."
L["Custom Recharge Color"] = "Color de recarga personalizado"
L["Enable/Disable per Form"] = "Activar/desactivar por forma"
L["Enhance 5 Bar minimum is %d (if you want less just change 5 bar color)"] = "El mínimo de las 5 barras de Mejora es %d (si quieres menos, cambia solo el color de la quinta barra)"
L["Multi"] = "Varios"
L["Recolor Text Instead Of Bar"] = "Colorear el texto en lugar de la barra"
L["Show rune count in center and remove recharge text/animation"] = "Mostrar el número de runas en el centro y quitar el texto y la animación de recarga"
L["Show the resource text only while the power bar is hidden - disabled, filtered off for this spec, a spec with no power, or hidden by \"Hide Power Bar if Resource\". Off = always show the text."] = "Muestra el texto del recurso solo mientras la barra de poder está oculta: desactivada, filtrada para esta especialización, en una especialización sin poder u oculta con «Ocultar la barra de poder si hay recurso». Desactivado = el texto se ve siempre."
L["Single-threshold options don't apply while Multi-band coloring is on."] = "Las opciones de umbral único no se aplican mientras Colores por franjas está activado."
L["Threshold Options"] = "Opciones del umbral"
L["Threshold as"] = "Umbral en"
L["Threshold color below value"] = "Color del umbral por debajo del valor"
L["Unavailable with Enhancement 5-bar style."] = "No disponible con el estilo de 5 barras de Mejora."
L["Value"] = "Valor"
L["When the class resource bar is not shown, this automatically adds the class resource height to the power bar."] = "Cuando no se muestra la barra del recurso de clase, añade sola su altura a la barra de poder."
L["click to edit"] = "haz clic para editar"
L["Fill Settings"] = "Ajustes del relleno"
L["Show the bright spark at the leading edge of the cast bar fill."] = "Muestra la chispa brillante en el borde del relleno de la barra de hechizos."
L["Texture Settings"] = "Ajustes de la textura"
L["Opacity of the bar fill; below 100 the world shows through the fill instead of the background."] = "Opacidad del relleno de la barra; por debajo de 100 se ve el mundo a través del relleno en lugar del fondo."
L["Bar Layer"] = "Capa de la barra"
L["Native Colors"] = "Colores originales"
L["Desaturated"] = "Sin color"
L["Keep the cast bar visible (sitting empty) when you are not casting, instead of hiding it."] = "Mantiene visible la barra de hechizos (vacía) cuando no lanzas nada, en lugar de ocultarla."
L["Smooth Bar Animation"] = "Animación suave de la barra"
L["Eases the cast fill between updates. Turn off for a raw, uneased fill."] = "Suaviza el relleno entre actualizaciones. Desactívalo para un relleno directo, sin suavizar."
L["Show Fill Color When Idle"] = "Mostrar el color del relleno en reposo"
L["Opacity of the cast bar fill; below 100 the world shows through the fill instead of the background."] = "Opacidad del relleno de la barra de hechizos; por debajo de 100 se ve el mundo a través del relleno en lugar del fondo."
L["Colors the cast segment during which your interrupt will be available."] = "Colorea el tramo del hechizo en el que tendrás tu interrupción disponible."
L["Shows a small white tick mark where the cast will be when your interrupt comes off cooldown."] = "Muestra una pequeña marca blanca donde irá el hechizo cuando tu interrupción termine su reutilización."
L["Appends the cast target to the spell name (Spell Name - Target), class colored, and disables the separate Spell Target display."] = "Añade el objetivo del hechizo al nombre (Nombre del hechizo - Objetivo), con color de clase, y desactiva la opción aparte Mostrar objetivo del hechizo."
L["Choose background per bar"] = "Elegir el fondo de cada barra"
L["Pip Border"] = "Borde de los puntos"
L["Border on individual pips"] = "Borde en cada punto"

