L["Show reminders when remaining buff time is below this many minutes.\n0 = only when fully expired.\nIgnored in combat and during Mythic+ keys (then only when the buff is gone)."] = "Muestra los recordatorios cuando al beneficio le quedan menos de estos minutos.\n0 = solo cuando se ha acabado del todo.\nNo cuenta en combate ni durante las llaves de M+ (entonces solo cuando el beneficio ya no está)."
L["Reminder threshold while you are in a dungeon before a Mythic+ key starts (Mythic 0 / keystone lobby). Set it high enough that you top up buffs and food before pulling, so you begin the key with enough duration to last it.\n0 = only when fully expired.\nIgnored once the key is active or you are in combat (then only when the buff is fully gone)."] = "Umbral del recordatorio mientras estás en una mazmorra antes de empezar una llave de M+ (mítica 0 / esperando con la piedra angular). Ponlo lo bastante alto para renovar beneficios y comida antes de empezar, y así empezar la llave con duración suficiente para toda ella.\n0 = solo cuando se ha acabado del todo.\nNo cuenta cuando la llave ya ha empezado o estás en combate (entonces solo cuando el beneficio se ha acabado del todo)."
L["Where to Show"] = "Dónde mostrar"
L["Pick which content this section's reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "Elige en qué contenido salen los recordatorios de esta sección.\nEn las zonas de descanso (ciudades y posadas) nunca salen."
L["Others are missing my buff"] = "A otros les falta mi beneficio"
L["I am missing others' buffs"] = "A mí me faltan beneficios de otros"
L["Others are missing my buff: remind when a groupmate is missing a buff you can cast.\nI am missing others' buffs: remind when you are missing a buff a groupmate could give you (only shown when someone who can cast it is present). Off by default."] = "A otros les falta mi beneficio: avisa cuando a alguien del grupo le falta un beneficio que puedes dar tú.\nA mí me faltan beneficios de otros: avisa cuando te falta un beneficio que te podría dar alguien del grupo (solo sale si hay alguien que pueda darlo). Desactivado de forma predeterminada."
L["Pick which content these consumable reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "Elige en qué contenido salen estos recordatorios de consumibles.\nEn las zonas de descanso (ciudades y posadas) nunca salen."
