L["The macro editor: tabs, icon grid, text well, and buttons."] = "El editor de macros: pestañas, cuadrícula de iconos, cuadro de texto y botones."
L["The mailbox: inbox rows, send mail, open mail, and attachment slots."] = "El buzón: filas del correo recibido, enviar correo, abrir correo y huecos de adjuntos."
L["The monthly calendar grid, event dialogs, and navigation arrows."] = "La cuadrícula del calendario del mes, las ventanas de eventos y las flechas para moverse."
L["The NPC dialog window: greeting text, gossip and quest options, and goodbye button."] = "La ventana de diálogo de los PNJ: saludo, opciones de conversación y de misiones, y botón de despedida."
L["The NPC quest window: quest detail, progress, and reward panels plus the multi-quest greeting list."] = "La ventana de misiones de los PNJ: detalles de la misión, progreso y recompensas, y la lista de saludo con varias misiones."
L["The Player Spells window: talents, spec selection, and the spellbook."] = "La ventana de hechizos del jugador: talentos, elección de especialización y libro de hechizos."
L["The profession crafting window: recipe list, schematic, specializations, and crafting orders."] = "La ventana de fabricación de profesión: lista de recetas, esquema, especializaciones y pedidos de fabricación."
