L["Blizzard's windows match the EllesmereUI theme with a WoW 2.0 Dark Theme, from the Dungeon Journal to the Auction House and beyond."] = "Las ventanas de Blizzard siguen el tema de EllesmereUI con un tema oscuro WoW 2.0, desde la guía de mazmorras hasta la casa de subastas y más."
L["Changing the Group Finder reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "Para cambiar del todo entre el aspecto de Blizzard y el de Ellesmere en el buscador de grupos hay que recargar la interfaz."
L["Remembers the Tank/Healer/DPS roles you last applied with and restores them the next time you sign up to a premade group (limited to roles your current spec can fill)."] = "Recuerda las funciones de tanque/sanador/DPS con las que te apuntaste la última vez y las vuelve a poner la próxima vez que te inscribas en un grupo ya creado (solo las que puede hacer tu especialización actual)."
L["Turns off ALL window skinning for this profile. Requires a reload."] = "Desactiva TODO el cambio de aspecto de las ventanas en este perfil. Hay que recargar."
L["Adds a strip down the left edge of a loot toast in the item's quality color. The flat skin drops Blizzard's quality ring around the icon, so this puts that rarity cue back."] = "Añade una franja en el borde izquierdo del aviso de botín con el color de la calidad del objeto. El aspecto plano quita el anillo de calidad de Blizzard alrededor del icono, así que esto devuelve esa pista de rareza."
L["Also show the strip on gold toasts, in the header's gold color. Gold has no rarity to signal, so this is off by default."] = "Muestra la franja también en los avisos de oro, con el color dorado del título. El oro no tiene rareza que indicar, así que está desactivado de forma predeterminada."
L["Gold Toast Strip"] = "Franja en los avisos de oro"
L["Toast Scale"] = "Escala de los avisos"
L["Scales the loot and gold toasts."] = "Cambia el tamaño de los avisos de botín y de oro."
L["Item Upgrades"] = "Mejoras de objetos"
L["The item upgrade window: upgrade slot, track selector, cost, and the currency strip."] = "La ventana de mejora de objetos: hueco de mejora, elección de rango, coste y franja de monedas."
L["Changing the Item Upgrades reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "Para cambiar del todo entre el aspecto de Blizzard y el de Ellesmere en las mejoras de objetos hay que recargar la interfaz."
L["Loot Window"] = "Ventana de botín"
L["The loot window: item rows with squared icons, kept item quality colors."] = "La ventana de botín: filas de objetos con iconos cuadrados y los colores de calidad de siempre."
L["Changing the Loot Window reskin requires a UI reload to fully swap between Blizzard and Ellesmere styles."] = "Para cambiar del todo entre el aspecto de Blizzard y el de Ellesmere en la ventana de botín hay que recargar la interfaz."
L["Loot Toasts"] = "Avisos de botín"
L["The \"You received\" popups for loot, currency, and upgrades."] = "Las ventanas de «Has recibido» del botín, las monedas y las mejoras."
