L["Split this stack into empty slots repeatedly until only the chosen amount or less remains. Alt+Enter does the same."] = "Divide este montón en huecos vacíos una y otra vez hasta que solo quede la cantidad elegida o menos. Alt+Intro hace lo mismo."
