L["Also use the split dialog with Auto Split in OneBag, MultiBag, the reagent bag, the bank and the guild bank, replacing Blizzard's split popup there. All Items and category views always use it."] = "Usa también la ventana de dividir con División automática en OneBag, MultiBag, la bolsa de componentes, el banco y el banco de hermandad, en lugar de la ventana de dividir de Blizzard. Todos los objetos y las vistas por categoría la usan siempre."
