L["Display Binds on Equipped / Warbound until Equipped on equipment items in your bags and bank."] = "Muestra «Se liga al equiparlo» / «Ligado a la banda guerrera hasta que te equipas con ello» en las piezas de equipo de tus bolsas y del banco."
L["Display item levels on equipment items in the inventory."] = "Muestra el nivel de objeto de las piezas de equipo en el inventario."
L["Display junk items in a greyed-out style."] = "Muestra la chatarra en gris."
L["Enhanced inventory system with sidebar categories, item levels, and quality borders."] = "Sistema de inventario mejorado con categorías en la barra lateral, niveles de objeto y bordes de calidad."
