L["Font size for item level numbers on equipment items."] = "Tamaño de letra del nivel de objeto de las piezas de equipo."
L["Font size for stack counts, keystone levels, and dungeon abbreviations."] = "Tamaño de letra de los números de montón, los niveles de piedra angular y las abreviaturas de mazmorras."
L["Grow the bag window (more columns + taller, keeping its shape) so all of the active tab's slots are visible without scrolling. It only grows while open -- switching to a bigger tab enlarges it, smaller tabs keep the size -- and resets when you close the bags. Never smaller than your normal size."] = "Agranda la ventana de las bolsas (más columnas y más alta, sin cambiar su forma) para que se vean todos los huecos de la pestaña activa sin desplazarse. Solo crece mientras está abierta (pasar a una pestaña más grande la agranda; las más pequeñas mantienen el tamaño) y vuelve a su tamaño al cerrar las bolsas. Nunca es más pequeña que tu tamaño normal."
L["Grow the bag window (more columns + taller, keeping its shape) so all of the active tab's slots are visible without scrolling. It only grows while open -- switching to a bigger tab enlarges it, smaller tabs keep the size -- and resets when you close the bags."] = "Agranda la ventana de las bolsas (más columnas y más alta, sin cambiar su forma) para que se vean todos los huecos de la pestaña activa sin desplazarse. Solo crece mientras está abierta (pasar a una pestaña más grande la agranda; las más pequeñas mantienen el tamaño) y vuelve a su tamaño al cerrar las bolsas."
L["Hide sidebar categories that have no items in them."] = "Oculta las categorías de la barra lateral que no tienen objetos."
L["Hides Pinned Items. Re-show in settings."] = "Oculta los objetos fijados. Se vuelven a mostrar en los ajustes."
L["Hides Recent Items. Re-show in settings."] = "Oculta los objetos recientes. Se vuelven a mostrar en los ajustes."
L["Hides the Add Category button at the bottom of the bag sidebar."] = "Oculta el botón Añadir categoría de la parte de abajo de la barra lateral de las bolsas."
L["In the All Items bag view, show each category's items under indented expansion sub-headers (newest expansions first), even when everything in that category is from one expansion."] = "En la vista Todos los objetos, muestra los objetos de cada categoría bajo subtítulos de expansión con sangría (las más nuevas primero), aunque todo lo de esa categoría sea de una sola expansión."
L["MultiBag uses Blizzard's built-in sorting system, which reorganizes the items in your default Blizzard bags. The changes persist even if you disable EllesmereUI Bags."] = "MultiBag usa el sistema de orden de Blizzard, que reorganiza los objetos en tus bolsas normales de Blizzard. Los cambios se mantienen aunque desactives las bolsas de EllesmereUI."
