L["Cosmetic"] = "Cosmético"
L["In The Armory and the Weapons / Trinkets, Armor, and Item Set Gear category views, group items under equip-slot sub-headers (Head, Shoulders, Chest, Cosmetic, ...). Does not add sidebar views."] = "En El Arsenal y en las vistas de categoría Armas / abalorios, Armadura y Equipo de conjunto, agrupa los objetos bajo subtítulos por hueco (cabeza, hombros, torso, cosmético...). No añade vistas a la barra lateral."
L["Set Name Text Options"] = "Opciones del texto del nombre del conjunto"
L["Show copies of the same item in separate bag slots as one icon or row, with their counts added together. Gear is never merged, and OneBag and MultiBag always show every slot. Merging pauses while the mail, trade, auction house, vendor, bank or guild bank window is open."] = "Muestra las copias del mismo objeto que están en huecos distintos como un solo icono o fila, con sus cantidades sumadas. El equipo nunca se junta, y OneBag y MultiBag siempre muestran todos los huecos. Se deja de juntar mientras están abiertas las ventanas de correo, comercio, casa de subastas, mercader, banco o banco de hermandad."
