L["A standalone cast bar for this unit, placeable anywhere in Unlock Mode. Runs alongside the Unit Frames cast bars."] = "Una barra de hechizos independiente para esta unidad, que puedes poner donde quieras en el modo desbloqueo. Funciona junto a las barras de hechizos de los marcos de unidad."
L["Flash the cast bar and show \"Interrupted\" for a moment when the cast is interrupted."] = "Hace destellar la barra de hechizos y muestra «Interrumpido» un momento cuando se interrumpe el hechizo."
L["Preview the bars at their position"] = "Vista previa de las barras en su posición"
L["Show one plain cast bar per enemy nameplate that is casting, gathered into a single movable group with the spell name, its target, and the cast timer."] = "Muestra una barra de hechizos sencilla por cada placa de nombre enemiga que está lanzando, juntas en un grupo que puedes mover, con el nombre del hechizo, su objetivo y el temporizador."
L["Show who each spell is being cast on, exactly like the nameplate cast bars."] = "Muestra sobre quién se lanza cada hechizo, igual que las barras de hechizos de las placas de nombre."
L["Show who the spell is being cast on, exactly like the nameplate cast bars."] = "Muestra sobre quién se lanza el hechizo, igual que las barras de hechizos de las placas de nombre."
L["Shows where your interrupt will be ready during a cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "Muestra dónde tendrás lista la interrupción durante un hechizo. «Marca» señala el punto exacto en la barra de hechizos; «Marca + barra» además colorea el tramo en el que tendrás la interrupción disponible."
L["The most cast bars shown at once. Extra casters take a bar as soon as one frees up."] = "El máximo de barras de hechizos a la vez. Los demás lanzadores cogen barra en cuanto queda una libre."
L["Which way new bars stack as more enemies start casting."] = "Hacia dónde se apilan las barras nuevas cuando más enemigos empiezan a lanzar."
